// Windowless test for tcl_lsp.cpp -- the analysis half of mep's own
// Tcl language server (`mep-tcl-lsp`). Drives the pure functions
// directly: no process, no JSON-RPC client. CHECK(), never assert(): the
// Release build strips assert(). Generated by tools/new_language.py.
#include <cstdio>
#include <cstdlib>
#include <string>
#include <vector>

#include "tcl_lsp.h"

namespace {
int g_checks = 0;

void Check(bool ok, const char *expr, int line) {
    g_checks++;
    if (ok) return;
    std::fprintf(stderr, "CHECK FAILED: %s at %s:%d\n", expr, __FILE__, line);
    std::abort();
}
#define CHECK(c) Check((c), #c, __LINE__)

std::vector<std::string> L(const std::string &text) {
    std::vector<std::string> out;
    std::string cur;
    for (char c : text) {
        if (c == '\n') {
            out.push_back(cur);
            cur.clear();
        } else {
            cur += c;
        }
    }
    out.push_back(cur);
    return out;
}

const char *kSample =
    "# Greets someone.\n"                                   // 0
    "proc ::app::greet {name {greeting hello}} {\n"        // 1
    "    set msg \"$greeting, $name\"\n"                    // 2
    "    if {[string length $name] > 10} {\n"               // 3
    "        set msg [string range $msg 0 9]\n"             // 4
    "    }\n"                                               // 5
    "    puts $msg\n"                                       // 6
    "}\n"                                                   // 7
    "namespace eval app {\n"                               // 8
    "    variable count 0\n"                                // 9
    "    proc run {} {\n"                                   // 10
    "        variable count\n"                              // 11
    "        incr count\n"                                  // 12
    "        greet world\n"                                 // 13
    "    }\n"                                               // 14
    "}\n"                                                   // 15
    "oo::class create Counter {\n"                          // 16
    "    variable n\n"                                      // 17
    "    method bump {} { incr n }\n"                       // 18
    "}\n"                                                   // 19
    "::app::greet bob\n";                                   // 20

bool HasCode(const std::vector<TclLspDiagnostic> &ds, const std::string &code, int line) {
    for (const auto &d : ds)
        if (d.code == code && d.range.line == line) return true;
    return false;
}

void TestCleanFile() {
    const auto doc = TclLspAnalyze(L(kSample));
    const auto ds = TclLspDiagnostics(*doc);
    for (const auto &d : ds) std::fprintf(stderr, "unexpected: %s\n", TclLspFormatDiagnostic("x", d).c_str());
    CHECK(ds.empty());
}

void TestSyntaxErrors() {
    // Tcl's own messages, where Tcl points.
    auto one = [](const std::string &src) {
        const auto ds = TclLspDiagnostics(*TclLspAnalyze(L(src)));
        return ds.empty() ? TclLspDiagnostic() : ds[0];
    };
    TclLspDiagnostic d = one("set a {x\n");
    CHECK(d.code == "syntax-error" && d.message == "missing close-brace" && d.range.line == 0 && d.range.col == 6);
    d = one("puts ok\nset b \"x\"y\n");
    CHECK(d.message == "extra characters after close-quote" && d.range.line == 1 && d.range.col == 9);
    d = one("set x [foo\n");
    CHECK(d.message == "missing close-bracket" && d.range.col == 6);
    d = one("puts ${a\n");
    CHECK(d.message == "missing close-brace for variable name");
    d = one("proc f {} {\n    expr {1 +}\n}\n");
    CHECK(d.message == "missing operand at _@_ in expression \"1 +_@_\"" && d.range.line == 1);
    d = one("if {$a eq b} {}\n");
    CHECK(d.message.compare(0, 23, "invalid bareword \"b\" in") == 0);
    d = one("while {(1} {}\n");
    CHECK(d.message == "unbalanced open paren in expression \"(1\"");
    d = one("proc f {} {\n  #if {\n}\n");
    CHECK(d.message == "missing close-brace: possible unbalanced brace in comment");
    d = one("expr {08 + 1}\n");
    CHECK(d.message.find("(invalid octal number?)") != std::string::npos);
    // A [command] inside an expression inside a proc.
    d = one("proc f {} {\n    if {[llength \"a]} {}\n}\n");
    CHECK(d.message == "missing \" in expression \"[llength \"a]\"" && d.range.line == 1);
}

void TestLints() {
    const auto ds = TclLspDiagnostics(*TclLspAnalyze(L("proc f {items} {\n"         // 0
                                                         "    set unused 1\n"        // 1
                                                         "    set n [llength items]\n"  // 2
                                                         "    expr $n + 1\n"         // 3
                                                         "    string length\n"       // 4
                                                         "    string lenx $n\n"      // 5
                                                         "    regexp {a(b)} $n all sub\n"  // 6
                                                         "    return $n\n"           // 7
                                                         "}\n")));
    CHECK(HasCode(ds, "unused-variable", 1));
    CHECK(HasCode(ds, "missing-dollar", 2));
    CHECK(HasCode(ds, "unbraced-expr", 3));
    CHECK(HasCode(ds, "wrong-args", 4));
    CHECK(HasCode(ds, "unknown-subcommand", 5));
    CHECK(!HasCode(ds, "unused-variable", 6));  // regexp's match variables are placeholders
    for (const auto &d : ds)
        if (d.code == "wrong-args") CHECK(d.message == "wrong # args: should be \"string length string\"");
    // A proc of the same name cancels the builtin's checks; `string len` is a unique prefix.
    CHECK(TclLspDiagnostics(*TclLspAnalyze(L("proc set {a b c} {}\nset 1 2 3\nstring len x\n"))).empty());
    // eval / info locals make a proc's variables unknowable.
    CHECK(TclLspDiagnostics(*TclLspAnalyze(L("proc f {} {\n set x 1\n eval $::cmd\n}\n"))).empty());
    // `if $done` and `expr $e` evaluate a value on purpose.
    CHECK(TclLspDiagnostics(*TclLspAnalyze(L("if $done {puts y}\nset v [expr $e]\n"))).empty());
}

void TestHover() {
    const auto doc = TclLspAnalyze(L(kSample));
    TclLspHoverInfo h = TclLspHover(*doc, 3, 11);  // string
    CHECK(h.found && h.text.find("string subcommand") != std::string::npos);
    h = TclLspHover(*doc, 3, 17);  // length
    CHECK(h.found && h.text.find("string length string") != std::string::npos);
    h = TclLspHover(*doc, 13, 9);  // greet -> ::app::greet
    CHECK(h.found && h.text.find("proc ::app::greet {name {greeting hello}}") != std::string::npos);
    CHECK(h.text.find("Greets someone.") != std::string::npos);
    h = TclLspHover(*doc, 2, 9);  // msg
    CHECK(h.found && h.text.find("local variable msg") != std::string::npos);
    h = TclLspHover(*doc, 2, 18);  // $greeting
    CHECK(h.found && h.text.find("parameter greeting") != std::string::npos);
    const auto d2 = TclLspAnalyze(L("expr {sqrt(2)}\n"));
    h = TclLspHover(*d2, 0, 7);
    CHECK(h.found && h.text.find("sqrt") != std::string::npos);
}

bool HasItem(const std::vector<TclLspCompletionItem> &items, const std::string &label) {
    for (const auto &i : items)
        if (i.label == label) return true;
    return false;
}

void TestCompletion() {
    auto doc = TclLspAnalyze(L("proc f {alpha} {\n    set beta 1\n    puts $\n}\n"));
    auto items = TclLspCompletions(*doc, 2, 10);
    CHECK(HasItem(items, "alpha") && HasItem(items, "beta") && !HasItem(items, "env"));
    doc = TclLspAnalyze(L("str\n"));
    items = TclLspCompletions(*doc, 0, 3);
    CHECK(HasItem(items, "string") && !HasItem(items, "set"));
    CHECK(items[0].replace_start == 0 && items[0].replace_end == 3);
    doc = TclLspAnalyze(L("set n [string le\n"));
    items = TclLspCompletions(*doc, 0, 16);
    CHECK(HasItem(items, "length") && !HasItem(items, "range"));
    doc = TclLspAnalyze(L("proc greet {} {}\ngr\n"));
    items = TclLspCompletions(*doc, 1, 2);
    CHECK(HasItem(items, "greet"));
}

void TestSignature() {
    const auto doc = TclLspAnalyze(L("string range $s 0 \nlsort -unique \n"));
    TclLspSignatureHelp sh = TclLspSignatureAt(*doc, 0, 18);
    CHECK(sh.found && sh.label == "string range string first last");
    CHECK(sh.params.size() == 3 && sh.active_param == 2);
    const auto d2 = TclLspAnalyze(L(kSample));
    sh = TclLspSignatureAt(*d2, 13, 15);
    CHECK(sh.found && sh.label == "::app::greet name {greeting hello}");
}

void TestNavigation() {
    const auto doc = TclLspAnalyze(L(kSample));
    // $msg on line 6 -> `set msg` on line 2.
    auto defs = TclLspDefinition(*doc, 6, 11);
    CHECK(defs.size() == 1 && defs[0].range.line == 2 && defs[0].range.col == 8);
    auto refs = TclLspReferences(*doc, 2, 9);
    CHECK(refs.size() == 4);  // set msg, set msg, $msg (line 4), $msg (line 6)
    // greet: the definition, the call inside namespace app, the qualified call.
    refs = TclLspReferences(*doc, 13, 9);
    CHECK(refs.size() == 3);
    defs = TclLspDefinition(*doc, 20, 8);
    CHECK(defs.size() == 1 && defs[0].range.line == 1);
    // `variable count` in run links to the namespace's count.
    refs = TclLspReferences(*doc, 12, 14);
    CHECK(refs.size() == 3);
    std::string err;
    auto edits = TclLspRename(*doc, 13, 9, "hello", &err);
    CHECK(edits.size() == 3);
    for (const auto &e : edits) CHECK(e.new_text == "hello" && e.range.end_col - e.range.col == 5);
    const auto pr = TclLspPrepareRename(*doc, 20, 10);
    CHECK(pr.found && pr.placeholder == "greet" && pr.range.col == 7);
    edits = TclLspRename(*doc, 2, 9, "bad name", &err);
    CHECK(edits.empty() && !err.empty());
}

void TestSymbolsAndFolds() {
    const auto doc = TclLspAnalyze(L(kSample));
    const auto syms = TclLspSymbols(*doc);
    std::string got;
    for (const auto &s : syms) got += s.name + "/" + std::to_string(s.parent) + " ";
    if (got != "::app::greet/-1 app/-1 count/1 run/1 Counter/-1 n/4 bump/4 ") std::fprintf(stderr, "symbols: %s\n", got.c_str());
    CHECK(got == "::app::greet/-1 app/-1 count/1 run/1 Counter/-1 n/4 bump/4 ");
    const auto folds = TclLspFolds(*doc);
    bool body = false;
    for (const auto &f : folds)
        if (f.start_line == 1 && f.end_line == 6) body = true;
    CHECK(body);
}

void TestFormat() {
    std::string err;
    const auto edits = TclLspFormat(L("proc f {} {\nputs x\n}"), 100, &err);
    CHECK(err.empty() && edits.size() == 1 && edits[0].new_text.find("    puts x") != std::string::npos);
    CHECK(TclLspFormat(L("proc f {} {\n    puts x\n}\n"), 100, &err).empty());
}

void TestParseReport() {
    const std::string r = TclLspParseReport("if {$a} {puts [b]}\n");
    CHECK(r == "script 0 19 ok\nexpr 4 6 ok\nscript 9 17 ok\ncmd 15 17 ok\n");
}

void TestRobustness() {
    // Every query at every position of every prefix of a file must not crash.
    const std::string src = std::string(kSample) +
                            "switch -glob -- $x {\n  a* { set y [expr {$x ** 2}] }\n  default -\n  b {}\n}\n"
                            "try { open f } on error {msg opts} { puts $msg } finally { close $f }\n"
                            "dict for {k v} $d { lappend out $k }\nforeach {a b} $l { set c {*}$a }\n"
                            "set s \"a\\\n b $arr(x$y) [list \\{]\"\n";
    for (size_t n = 0; n <= src.size(); n += 3) {
        const auto lines = L(src.substr(0, n));
        const auto doc = TclLspAnalyze(lines);
        TclLspDiagnostics(*doc);
        TclLspSymbols(*doc);
        TclLspFolds(*doc);
        const int last = static_cast<int>(lines.size()) - 1;
        for (int col = 0; col <= static_cast<int>(lines.back().size()); col++) {
            TclLspCompletions(*doc, last, col);
            TclLspHover(*doc, last, col);
            TclLspSignatureAt(*doc, last, col);
            TclLspDefinition(*doc, last, col);
            TclLspReferences(*doc, last, col);
            TclLspPrepareRename(*doc, last, col);
        }
    }
    // Deep nesting is cut off, not a stack overflow.
    std::string deep;
    for (int i = 0; i < 5000; i++) deep += "if 1 {";
    for (int i = 0; i < 5000; i++) deep += "}";
    TclLspDiagnostics(*TclLspAnalyze(L(deep)));
    std::string brackets(20000, '[');
    TclLspDiagnostics(*TclLspAnalyze(L(brackets)));
}

}  // namespace

int main() {
    TestCleanFile();
    TestSyntaxErrors();
    TestLints();
    TestHover();
    TestCompletion();
    TestSignature();
    TestNavigation();
    TestSymbolsAndFolds();
    TestFormat();
    TestParseReport();
    TestRobustness();
    std::printf("tcl_lsp_test: %d checks passed\n", g_checks);
    return 0;
}
